import json
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        import math
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda c: (_ for _ in ()).throw(ValueError("non-finite number")))
    except ValueError:
        raise
    except Exception as e:
        raise ValueError("invalid JSON") from e
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

import json
from pathlib import Path


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=_reject_constant)
    except ValueError:
        raise
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level JSON must be an object or array")
    return data


def _reject_constant(value):
    raise ValueError("non-finite number is not allowed")

import base64


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    payload = payloads[0]
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        payload = payload["result"]
    parts = payload["parts"]
    out_parts = []
    for part in parts:
        encoding = part.get("encoding")
        if encoding not in ("raw", "base64"):
            raise ValueError("unknown encoding")
        new_part = dict(part)
        raw = bytes.fromhex(part["hex"])
        if encoding == "raw":
            payload_bytes = raw
        else:
            b64 = base64.b64encode(raw).decode("ascii")
            payload_bytes = _wrap(b64).encode("ascii")
        new_part["payload_hex"] = payload_bytes.hex()
        out_parts.append(new_part)
    return {"name": contract["name"], "result": {"parts": out_parts}}


def _wrap(s):
    return "\r\n".join(s[i:i + 76] for i in range(0, len(s), 76))

import json
from pathlib import Path


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=_reject_constant)
    except ValueError:
        raise
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level JSON must be object or array")
    return data


def _reject_constant(value):
    raise ValueError("non-finite number not allowed")

import re

_BOUNDARY_RE = re.compile(r"^[A-Za-z0-9-]+$")


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    snapshot = payloads[0]
    encoding = payloads[1]

    boundary = snapshot.get("boundary")
    if not isinstance(boundary, str) or not boundary:
        raise ValueError("boundary must be non-empty str")
    if not _BOUNDARY_RE.match(boundary):
        raise ValueError("boundary must match [A-Za-z0-9-]+")

    parts = encoding.get("parts")
    if not isinstance(parts, list):
        raise ValueError("encoding parts must be a list")

    # Build each part's payload bytes and check boundary collision.
    rendered = []
    for part in parts:
        payload_hex = part.get("payload_hex")
        if not isinstance(payload_hex, str):
            raise ValueError("payload_hex must be str")
        try:
            payload_bytes = bytes.fromhex(payload_hex)
        except ValueError:
            raise ValueError("invalid payload_hex")
        if boundary.encode("utf-8") in payload_bytes:
            raise ValueError("boundary appears in payload")
        rendered.append((part, payload_bytes))

    out = bytearray()
    for part, payload_bytes in rendered:
        out += b"--" + boundary.encode("utf-8") + b"\r\n"
        if part.get("encoding") == "base64":
            out += b"Content-Transfer-Encoding: base64\r\n"
        mimetype = part.get("mimetype")
        if not isinstance(mimetype, str) or not mimetype:
            raise ValueError("mimetype must be non-empty str")
        out += b"Content-Type: " + mimetype.encode("utf-8") + b"\r\n"
        name = part.get("name")
        if not isinstance(name, str) or not name:
            raise ValueError("name must be non-empty str")
        disposition = 'form-data; name="' + name + '"'
        filename = part.get("filename")
        if filename is not None:
            if not isinstance(filename, str) or not filename:
                raise ValueError("filename must be non-empty str")
            disposition += '; filename="' + filename + '"'
        out += b"Content-Disposition: " + disposition.encode("utf-8") + b"\r\n"
        out += b"\r\n"
        out += payload_bytes
        out += b"\r\n"
    out += b"--" + boundary.encode("utf-8") + b"--\r\n"

    return {
        "name": contract["name"],
        "result": {
            "content_type": "multipart/form-data; boundary=" + boundary,
            "body_hex": bytes(out).hex(),
        },
    }

import re
from pathlib import Path

FIELD_NAME_RE = re.compile(r"^[A-Za-z0-9_.-]+$")
FILENAME_RE = re.compile(r"^[A-Za-z0-9_.-]+$")
MIME_RE = re.compile(r"^[A-Za-z0-9!#$%&'*+.^_`|~-]+/[A-Za-z0-9!#$%&'*+.^_`|~-]+$")

_EXT_MIME = {
    ".txt": "text/plain",
    ".json": "application/json",
    ".jpg": "image/jpeg",
}


def _basename(filename):
    return filename.rsplit("/", 1)[-1]


def _mime_for(filename, explicit):
    if explicit is not None:
        return explicit
    if filename is not None:
        for ext, mime in _EXT_MIME.items():
            if filename.lower().endswith(ext):
                return mime
    return "application/octet-stream"


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    payload = payloads[0]

    if not isinstance(payload, dict):
        raise ValueError("payload must be object")
    if "name" in payload and "result" in payload and set(payload) == {"name", "result"}:
        payload = payload["result"]

    fields = payload.get("fields")
    files = payload.get("files")
    boundary = payload.get("boundary")

    if not isinstance(fields, dict):
        raise ValueError("fields must be object")
    if not isinstance(files, dict):
        raise ValueError("files must be object")
    if not isinstance(boundary, str) or not boundary.strip():
        raise ValueError("boundary must be non-empty str")
    if not re.fullmatch(r"[A-Za-z0-9-]+", boundary):
        raise ValueError("boundary invalid")

    parts = []
    for name in sorted(fields.keys()):
        if not isinstance(name, str) or not FIELD_NAME_RE.fullmatch(name):
            raise ValueError("invalid field name")
        value = fields[name]

        if isinstance(value, str):
            # plain text
            parts.append({
                "name": name,
                "filename": None,
                "mimetype": "text/plain",
                "encoding": "raw",
                "hex": value.encode("utf-8").hex(),
            })
            continue

        if not isinstance(value, dict) or not value:
            raise ValueError("field value must be str or non-empty object")

        content = value.get("content")
        filename = value.get("filename")
        mimetype = value.get("mimetype")

        if content is not None and not isinstance(content, str):
            raise ValueError("content must be str")
        if filename is not None and not isinstance(filename, str):
            raise ValueError("filename must be str")
        if mimetype is not None and not isinstance(mimetype, str):
            raise ValueError("mimetype must be str")

        if mimetype is not None and not MIME_RE.fullmatch(mimetype):
            raise ValueError("invalid mimetype")

        if content is not None:
            # inline content
            data = content.encode("utf-8")
            encoding = "raw"
            if filename is not None:
                filename = _basename(filename)
                if not FILENAME_RE.fullmatch(filename):
                    raise ValueError("invalid filename")
            mime = _mime_for(filename, mimetype)
            parts.append({
                "name": name,
                "filename": filename,
                "mimetype": mime,
                "encoding": encoding,
                "hex": data.hex(),
            })
            continue

        # only filename -> read from files, base64
        if filename is None:
            raise ValueError("empty sub-object")
        if not isinstance(filename, str):
            raise ValueError("filename must be str")
        # filename is a safe relative path key into files
        if filename not in files:
            raise ValueError("missing file")
        hexdata = files[filename]
        if not isinstance(hexdata, str):
            raise ValueError("file hex must be str")
        try:
            data = bytes.fromhex(hexdata)
        except ValueError:
            raise ValueError("invalid hex")
        base = _basename(filename)
        if not FILENAME_RE.fullmatch(base):
            raise ValueError("invalid filename")
        mime = _mime_for(base, mimetype)
        parts.append({
            "name": name,
            "filename": base,
            "mimetype": mime,
            "encoding": "base64",
            "hex": data.hex(),
        })

    return {"name": contract["name"], "result": {"parts": parts}}

import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "body"))

from model import load_payload
from transform import transform


class TestBody(unittest.TestCase):
    def test_transform_shape_and_body(self):
        snapshot = {"boundary": "Bnd47"}
        encoding = {
            "parts": [
                {
                    "name": "title",
                    "filename": None,
                    "mimetype": "text/plain",
                    "encoding": "raw",
                    "payload_hex": "68656c6c6f".encode().hex(),
                },
                {
                    "name": "attachment",
                    "filename": "a.bin",
                    "mimetype": "application/octet-stream",
                    "encoding": "base64",
                    "payload_hex": "AAEC".encode().hex(),
                },
            ]
        }
        contract = {"name": "body", "operation": "multipart_body", "inputs": ["a", "b"], "output": "o"}
        result = transform([snapshot, encoding], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "body")
        self.assertEqual(result["result"]["content_type"], "multipart/form-data; boundary=Bnd47")
        body = bytes.fromhex(result["result"]["body_hex"])
        self.assertTrue(body.startswith(b"--Bnd47\r\n"))
        self.assertTrue(body.endswith(b"--Bnd47--\r\n"))
        # base64 part carries the transfer-encoding header
        self.assertIn(b"Content-Transfer-Encoding: base64\r\n", body)
        # raw part does not
        self.assertNotIn(b"Content-Transfer-Encoding: raw\r\n", body)

    def test_boundary_collision(self):
        snapshot = {"boundary": "abc"}
        encoding = {"parts": [{"name": "x", "filename": None, "mimetype": "text/plain", "encoding": "raw", "payload_hex": "616263".encode().hex()}]}
        contract = {"name": "body", "operation": "multipart_body", "inputs": ["a", "b"], "output": "o"}
        with self.assertRaises(ValueError):
            transform([snapshot, encoding], contract)

    def test_bad_boundary(self):
        snapshot = {"boundary": "bad boundary"}
        encoding = {"parts": []}
        contract = {"name": "body", "operation": "multipart_body", "inputs": ["a", "b"], "output": "o"}
        with self.assertRaises(ValueError):
            transform([snapshot, encoding], contract)


if __name__ == "__main__":
    unittest.main()

